  for (const tr of allRows) {
    const tds = Array.from(tr.querySelectorAll('td'));
    if (tds.length === 0) continue;

    const style = window.getComputedStyle(tr);
    const isHidden = style.display === 'none' || style.visibility === 'hidden' || tr.hidden;

    // Check classes / data attributes on tr
    const className = tr.className;
    const innerText = tr.innerText.trim();

    // Extract columns if standard row
    // Format: Airline, Ident, Aircraft, Status, Departure, Arrival
    data.push({
      className,
      isHidden,
      innerText: innerText.replace(/\s+/g, ' '),
      cells: tds.map(td => td.innerText.trim().replace(/\s+/g, ' '))
    });
  }
  return data;
});

