// Let's filter for all flights arriving between 8:00 PM and 11:00 PM
function parseTime(timeStr) {
  // e.g. "JFK 10:35PM EDT Fri" or "10:35PM"
  const match = timeStr.match(/(\d{1,2}):(\d{2})\s*(AM|PM)/i);
  if (!match) return null;
  let hours = parseInt(match[1], 10);
  const minutes = parseInt(match[2], 10);
  const ampm = match[3].toUpperCase();
  if (ampm === 'PM' && hours !== 12) hours += 12;
  if (ampm === 'AM' && hours === 12) hours = 0;
  return hours * 60 + minutes; // minutes from midnight
}

const windowStart = 20 * 60; // 8:00 PM = 20:00 = 1200 mins
const windowEnd = 23 * 60;   // 11:00 PM = 23:00 = 1380 mins

const matchingTimeFlights = result.filter(f => {
  const t = parseTime(f.arrival);
  return t !== null && t >= windowStart && t <= windowEnd;
});

console.log(`Total flights arriving 8:00 PM - 11:00 PM: ${matchingTimeFlights.length}`);
console.log(JSON.stringify(matchingTimeFlights, null, 2));

