const inspection = await browserjs(tabId, () => {
  // Check refine section
  const refineButtons = Array.from(document.querySelectorAll('a, button, span, div')).filter(el => {
    return el.textContent.includes('Refine') || el.textContent.includes('Airline') || el.textContent.includes('Showing');
  }).map(el => ({ tag: el.tagName, text: el.textContent.trim(), id: el.id, className: el.className }));

  // Check all tr elements
  const allRows = Array.from(document.querySelectorAll('table tr'));
  const parsedRows = allRows.map((tr, idx) => {
    const text = tr.innerText.trim();
    const style = window.getComputedStyle(tr);
    const display = style.display;
    const visibility = style.visibility;
    const isHidden = display === 'none' || visibility === 'hidden' || tr.hidden;
    return {
      idx,
      text: text.replace(/\s+/g, ' '),
      isHidden
    };
  }).filter(r => r.text.length > 0);

  return {
    refineButtons: refineButtons.slice(0, 10),
    totalTrElements: allRows.length,
    parsedRowCount: parsedRows.length,
    hiddenCount: parsedRows.filter(r => r.isHidden).length,
    visibleCount: parsedRows.filter(r => !r.isHidden).length,
    rows: parsedRows
  };
});

console.log("Total TR:", inspection.totalTrElements);
console.log("Parsed rows:", inspection.parsedRowCount);
console.log("Hidden count:", inspection.hiddenCount);
console.log("Visible count:", inspection.visibleCount);

